import type {Metadata} from "next";import {categories} from "@/lib/data";import {listVendors} from "@/services/vendors";import {VendorCard} from "@/components/vendor-card";import {Search,SlidersHorizontal} from "lucide-react";
export const metadata:Metadata={title:"Wedding Vendors in Egypt",description:"Discover talented wedding venues and vendors across Cairo, Giza and Alexandria."};
export default async function VendorsPage({searchParams}:{searchParams:Promise<{category?:string;city?:string;search?:string}>}){const p=await searchParams;const list=await listVendors(p);return <main className="mx-auto min-h-[70vh] max-w-[1320px] px-6 py-12 md:py-16"><div className="text-xs uppercase tracking-[.2em] text-[#a6796f]">Find your people</div><h1 className="serif mt-3 text-4xl md:text-6xl">Wedding vendors</h1><p className="mt-4 max-w-xl text-sm leading-6 text-[#817970]">A thoughtful collection of local talent for the day you have in mind.</p><form className="mt-8 grid gap-3 rounded-2xl border border-[#e9e4de] bg-white p-3 md:grid-cols-[1fr_220px_180px_auto]"><div className="flex items-center gap-3 px-3"><Search size={17} className="text-[#817970]"/><input name="search" defaultValue={p.search} placeholder="Try ‘garden venue’ or a vendor name" className="h-11 w-full bg-transparent text-sm outline-none"/></div><select name="category" defaultValue={p.category||""} className="h-11 rounded-lg border border-[#e9e4de] bg-white px-3 text-sm"><option value="">All categories</option>{categories.map(c=><option key={c}>{c}</option>)}</select><select name="city" defaultValue={p.city||""} className="h-11 rounded-lg border border-[#e9e4de] bg-white px-3 text-sm"><option value="">All cities</option>{["Cairo","Giza","Alexandria"].map(c=><option key={c}>{c}</option>)}</select><button className="flex items-center justify-center gap-2 rounded-xl bg-[#302d29] px-6 text-sm text-white"><SlidersHorizontal size={15}/>Find vendors</button></form><div className="mt-6 flex flex-wrap gap-2">{["All","Venues","Photography","Decoration","Makeup","Catering","Music","Flowers"].map(c=><a key={c} href={c==="All"?"/vendors":`/vendors?category=${c}`} className={`rounded-full border px-4 py-2 text-xs ${p.category===c?"border-[#302d29] bg-[#302d29] text-white":"border-[#e9e4de] bg-white hover:border-[#b77d71]"}`}>{c}</a>)}</div><div className="mt-8 flex items-center justify-between text-xs text-[#817970]"><span>{list.length} lovely places and people</span><span>Curated for celebrations in Egypt</span></div>{list.length?<div className="mt-5 grid gap-5 sm:grid-cols-2 lg:grid-cols-3">{list.map(v=><VendorCard key={v.id} vendor={v}/>)}</div>:<div className="mt-6 rounded-2xl border border-dashed border-[#d8d0c8] py-20 text-center text-sm text-[#817970]">No matches yet. Try a different city or category.</div>}</main>}
